-- Node: st-exc-pta (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Peritonsillar Abscess","body":"Open [Peritonsillar Abscess (adult assessment and disposition)](#/tree/peritonsillar-abscess) or [Peritonsillar Abscess Drainage](#/tree/pta-drainage) for the drainage technique and management pathway.\n\n**Peritonsillar abscess (quinsy)** is the most common deep infection of the head and neck: unilateral severe sore throat, trismus, a “hot potato”/muffled voice, uvular deviation away from the affected side, and a bulging, fluctuant peritonsillar swelling. [8]\n\n**Next 5 minutes:**\n- Assess the airway (usually not critically threatened, but trismus + swelling can compromise it — escalate if red flags).\n- **Drainage** — needle aspiration or incision and drainage of the abscess (see the PTA consult); ENT if drainage is difficult, recurrent, or the diagnosis is uncertain.\n- **Antibiotics** covering Strep + oral anaerobes (e.g., amoxicillin-clavulanate, or clindamycin; ampicillin-sulbactam IV if unable to tolerate PO/severe).\n- **Analgesia + IV fluids** (odynophagia limits intake); a single dose of IV/oral corticosteroid (dexamethasone) reduces pain and improves recovery.\n- Point-of-care ultrasound (intraoral) can differentiate abscess from cellulitis and guide drainage; CT if deep extension suspected.\n\n🛑 Cellulitis (no drainable pus) is treated with antibiotics + steroids, not drainage — ultrasound helps avoid a dry, painful stab. 🛑 Trismus severe enough to prevent drainage, or bilateral/atypical findings, warrants ENT and imaging.","citation":[8],"recommendation":"Drain the abscess (needle aspiration or I&D; ENT if difficult), antibiotics (Strep + anaerobe cover), analgesia, IV fluids, and a dose of dexamethasone. Ultrasound distinguishes abscess from cellulitis. Escalate airway if red flags.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'st-exc-pta' AND tree_id = 'sore-throat-hub';

-- Node: trach-vs-laryngectomy (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Tracheostomy or Laryngectomy?","body":"**Laryngectomy = Total surgical removal of larynx**\n- NO connection between oropharynx and airway\n- CANNOT be intubated from above\n- Stoma is the ONLY airway\n\n**Tracheostomy = Tube through trachea, larynx intact**\n- Upper airway may be patent\n- Can potentially oxygenate/intubate from above\n- Dual oxygenation strategy possible\n\n**If uncertain:** Attempt to feel airflow from mouth during ventilation. No airflow = likely laryngectomy. [1][2]","citation":[1,2],"options":[{"label":"Tracheostomy (upper airway intact)","next":"trach-assessment"},{"label":"Laryngectomy (stoma only airway)","next":"laryngectomy-emergency","urgency":"critical"},{"label":"Unknown - proceed with caution","next":"trach-assessment","urgency":"urgent"}],"images":[{"src":"images/trach-emergency/airway-routes-atlas.jpg","alt":"Sagittal comparison of a tracheostomy and a total laryngectomy with an end stoma.","caption":"A tracheostomy may retain upper airway continuity. After total laryngectomy the stoma is the only airway. Original myMedKitt atlas illustration."}],"summary":"Laryngectomy = NO oral airway possible; tracheostomy = dual airway — check bedside sign"}'::jsonb
WHERE id = 'trach-vs-laryngectomy' AND tree_id = 'trach-emergency';

-- Node: trach-tube-types (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Tracheostomy Tube Types","body":"**CUFFED vs UNCUFFED:**\n- **Cuffed:** Inflatable balloon creates seal for mechanical ventilation\n- **Uncuffed:** For spontaneous breathers, allows speech with finger occlusion\n\n**INNER CANNULA:**\n- Removable inner tube for easy cleaning\n- **ALWAYS remove inner cannula first** when troubleshooting obstruction\n- Not all tubes have inner cannulas\n\n**FENESTRATED:**\n- Holes in outer cannula allow airflow through vocal cords\n- Used for speech and weaning\n- **Must use non-fenestrated inner cannula for suctioning**\n- Fenestrations can cause granulation tissue formation\n\n**SPEAKING VALVES (Passy-Muir):**\n- One-way valve allows air through cords on exhalation\n- **MUST deflate cuff** before placing speaking valve\n- Remove immediately if respiratory distress [2][4][5]","citation":[2,4,5],"next":"trach-sizing","images":[{"src":"images/trach-emergency/trach-tube-anatomy.png","alt":"Diagram of fenestrated and non-fenestrated tracheostomy tubes","caption":"Trach tube anatomy: fenestrated (speaking valve compatible) vs non-fenestrated — inner cannula removal is first step in obstruction management (Cancer Research UK / Wikimedia Commons, CC BY-SA 4.0, PNG rendering)"}],"summary":"Cuffed vs uncuffed, inner cannula removal first for obstruction, deflate cuff before speaking valve","skippable":true}'::jsonb
WHERE id = 'trach-tube-types' AND tree_id = 'trach-emergency';

-- Node: trach-bleeding-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Bleeding: Timing & Severity","body":"[Open Tracheo-Innominate Fistula and RAPID](#/tree/tracheo-innominate-fistula) for suspected arterial hemorrhage.\n\n**Tracheostomy bleeding - assess timing and severity:**\n\n**Early bleeding (<48 hours post-op):**\n- Usually minor: skin edges, granulation\n- Related to suctioning, manipulation\n- Rarely life-threatening\n\n**Late bleeding (>72 hours, especially 7-14 days):**\n- **HIGH RISK for tracheo-innominate fistula (TIF)**\n- Innominate artery erosion - mortality approaches 50%\n- Any late bleeding may be \"sentinel bleed\" before massive hemorrhage\n\n**Sentinel bleed:**\n- Small self-limited bleed preceding massive hemorrhage (up to 50% of TIF cases)\n- **TREAT ANY LATE BLEEDING AS POTENTIAL TIF** [4][6][7][8]","citation":[4,6,7,8],"options":[{"label":"Minor oozing, stable patient","next":"trach-bleeding-minor"},{"label":"Moderate bleeding, 7-21 days post-trach","next":"trach-bleeding-tif-concern","urgency":"critical"},{"label":"Massive hemorrhage","next":"trach-bleeding-massive","urgency":"critical"}],"calculatorLinks":[{"id":"trach-bleeding","label":"Bleeding Risk Assessment"}],"summary":"Late bleeding >72h = sentinel bleed for tracheo-innominate fistula until proven otherwise","safetyLevel":"critical"}'::jsonb
WHERE id = 'trach-bleeding-start' AND tree_id = 'trach-emergency';

-- Node: tif-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Tracheo-Innominate Fistula","body":"[TIF Steps Summary](#/info/tif-steps)\n\n**Tracheo-Innominate Fistula (TIF)** is a catastrophic complication of tracheostomy with near-100% mortality without intervention and 50-70% mortality even with surgery. [1][2]\n\n**Key Principle:** Massive hemorrhage occurring 3 days to 6 weeks after tracheostomy is **TIF until proven otherwise**. [1][3]\n\n**Incidence:** 0.1-1% of tracheostomies; accounts for ~10% of significant tracheostomy bleeds. [2]\n\n**This consult covers:**\n- Recognizing the sentinel bleed (warning sign)\n- Cuff hyperinflation technique\n- Finger tamponade (Utley maneuver)\n- Surgical activation\n- Stabilization and airway management\n\n**Time is critical.** A sentinel bleed precedes massive hemorrhage by only 24-48 hours. [1][4]","citation":[1,2,3,4],"next":"tif-timing-check","images":[{"src":"images/tracheo-innominate-fistula/fistula-atlas.jpg","alt":"Paired cutaways of intact arterial and tracheal walls and a fistula carrying blood into the airway.","caption":"A defect between the innominate artery and anterior tracheal wall allows arterial blood to enter the airway. Schematic, not to scale. Original myMedKitt atlas illustration."}],"summary":"TIF is near-100% fatal without surgery; sentinel bleed precedes massive hemorrhage by 24-48 hours","skippable":true}'::jsonb
WHERE id = 'tif-start' AND tree_id = 'tracheo-innominate-fistula';

-- Node: tif-hyperinflate (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Hyperinflate Cuff - First Maneuver","body":"**Cuff hyperinflation is the FIRST-LINE maneuver for TIF bleeding.** [1][6]\n\n**Technique:**\n1. **Slowly add air** to the tracheostomy cuff balloon\n2. **Target:** ~50 mL total volume (much higher than normal)\n3. **Goal:** Tamponade the bleeding vessel by compressing against tracheal wall\n\n**Success rate: 85%** [6]\n\n**2024 data:** Cuff overinflation reduced mortality from 80% to 52.2% (p<0.001). [4]\n\n**Critical points:**\n- This is a **temporizing measure only**\n- Even successful tamponade can fail with tube movement\n- Continue to prepare for OR\n- Surgery is still required for definitive management\n\n**While hyperinflating:**\n- Call surgery if not already done\n- Activate MTP\n- Prepare finger tamponade equipment\n- Set up for oral intubation","citation":[1,4,6],"next":"tif-hyperinflate-result","images":[{"src":"images/tracheo-innominate-fistula/cuff-hyperinflation.svg","alt":"Cuff hyperinflation technique showing tracheostomy cuff inflated to tamponade the innominate artery against the tracheal wall","caption":"Cuff hyperinflation: inflate cuff with ~50 mL air to tamponade the innominate artery."}],"summary":"Hyperinflate trach cuff to ~50 mL as first maneuver — 85% success rate, temporizing only, prepare for OR","safetyLevel":"critical"}'::jsonb
WHERE id = 'tif-hyperinflate' AND tree_id = 'tracheo-innominate-fistula';

-- Node: tif-finger-tamponade (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Finger Tamponade - Utley Maneuver","body":"**The Utley maneuver is THE lifesaving bedside intervention when cuff hyperinflation fails.** [1][7]\n\n**Success rate: >80%** for controlling hemorrhage via direct tamponade. [7]\n\n**CRITICAL RULE:** The provider who performs this maneuver **MUST NOT MOVE THEIR FINGER until the patient is in the OR under surgical care.** [1][7]\n\n**You will be physically attached to this patient during transport to OR.**\n\n**Before starting:**\n1. Ensure airway backup plan (oral ETT ready)\n2. Have surgical team en route\n3. Blood products running or ready\n4. OR notified and preparing\n5. Transport team assembled","citation":[1,7],"next":"tif-utley-technique","images":[{"src":"images/tracheo-innominate-fistula/utley-maneuver.svg","alt":"Utley maneuver technique showing finger inserted through tracheostomy stoma compressing the innominate artery against the posterior sternum","caption":"Utley maneuver: finger through stoma compresses innominate artery against sternum."}],"summary":"Utley maneuver is the lifesaving bedside intervention — >80% success; provider stays attached to patient until OR","safetyLevel":"critical"}'::jsonb
WHERE id = 'tif-finger-tamponade' AND tree_id = 'tracheo-innominate-fistula';

-- Node: tif-utley-technique (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Utley Maneuver - Step by Step","body":"**Finger Tamponade Technique:** [1][7]\n\n**Step 1 - Secure Airway:**\n- Deflate tracheostomy cuff\n- Insert cuffed oral ETT **deep** (cuff 2 cm past stoma)\n- Inflate ETT cuff\n- Confirm ventilation\n\n**Step 2 - Remove Tracheostomy:**\n- With airway secured, remove tracheostomy tube\n- May need to **extend stoma incision vertically** for access\n\n**Step 3 - Insert Finger:**\n- Insert index finger through stoma into **pretracheal space**\n- Use blunt dissection to create space if needed\n- Advance finger anteriorly\n\n**Step 4 - Compress Artery:**\n- Compress innominate artery **anteriorly against posterior sternum/manubrium**\n- Apply firm, steady pressure\n\n**Step 5 - External Counter-Pressure:**\n- Place thumb in sternal notch\n- \"Pinch\" the artery between finger and thumb\n\n**Step 6 - MAINTAIN PRESSURE:**\n- Do NOT release until patient is in OR under surgical care\n- You are now attached to this patient","citation":[1,7],"next":"tif-utley-considerations","images":[{"src":"images/tracheo-innominate-fistula/utley-maneuver.svg","alt":"Utley maneuver step-by-step showing finger through stoma compressing the innominate artery against the posterior sternum","caption":"Utley maneuver: finger through stoma, compress artery anteriorly against sternum."}],"summary":"Secure oral ETT first, remove trach, finger through stoma into pretracheal space, compress artery vs sternum","safetyLevel":"critical"}'::jsonb
WHERE id = 'tif-utley-technique' AND tree_id = 'tracheo-innominate-fistula';

